// Bütçe sapmasının saf mantığı: toplamlar, sapma, ortak ölçek ve yazımlar. Para TRY'dir; sayılar ABACUS'tandır.
import { math, money } from "@snn/abacus-core";
import { formatMoney, formatMoneyCompact, formatPercent } from "../lib/chart-format";

export interface VarianceItem { key: string; name: string; budget: number; actual: number }
export interface VarianceDepartment {
  key: string;
  name: string;
  /** Sorumlu kişinin adı (avatar için). */
  owner?: string | undefined;
  /** Kalemler verilirse bütçe ve gerçekleşen kalemlerden toplanır; verilmezse aşağıdaki değerler kullanılır. */
  items?: VarianceItem[] | undefined;
  budget?: number | undefined;
  actual?: number | undefined;
}

export interface Resolved { key: string; name: string; owner?: string | undefined; budget: number; actual: number; items: VarianceItem[] }

/** Bölümü kalemlerinden toplayarak çözer: toplamlar kalemlerle tutarlı olmak zorundadır. */
export function resolveDepartment(department: VarianceDepartment): Resolved {
  const items = department.items ?? [];
  const budget = items.length ? items.reduce((sum, item) => sum + item.budget, 0) : department.budget ?? 0;
  const actual = items.length ? items.reduce((sum, item) => sum + item.actual, 0) : department.actual ?? 0;
  return { key: department.key, name: department.name, owner: department.owner, budget, actual, items };
}

export type VarianceKind = "over" | "under" | "on";

/** Sapma: gerçekleşen - bütçe (gider: pozitif aşım). `tolerance`: bütçeye oranla "plana uygun" bandı. */
export function variance(budget: number, actual: number, tolerance = .02): { amount: number; percent: number | null; kind: VarianceKind } {
  const amount = actual - budget;
  const percent = math.percentChange(actual, budget);
  const kind: VarianceKind = budget > 0 && Math.abs(amount) <= budget * tolerance ? "on" : amount > 0 ? "over" : amount < 0 ? "under" : "on";
  return { amount, percent, kind };
}

export const kindWord = (kind: VarianceKind) => kind === "over" ? "aşım" : kind === "under" ? "altında" : "plana uygun";

/** İşaretli tutar: "+₺12.000", "-₺8.500" (eksi ABACUS'tan). */
export function signedMoney(amount: number): string {
  const rounded = Math.round(amount);
  return rounded > 0 ? `+${formatMoney(rounded, 0)}` : formatMoney(rounded, 0);
}

/** Sapma yüzdesi ve sözü: "+%12,3 aşım", "-%4,0 altında", "plana uygun". Bütçe sıfırsa yalnız söz. */
export function variancePercentText(budget: number, actual: number, tolerance = .02): string {
  const { percent, kind } = variance(budget, actual, tolerance);
  if (kind === "on" || percent === null) return kindWord(kind);
  return `${money.percent(percent, 1, { sign: "always" })} ${kindWord(kind)}`;
}

export const moneyFull = (value: number) => formatMoney(Math.round(value), 0);
export const moneyShort = (value: number) => formatMoneyCompact(Math.round(value));
export const scalePercent = (ratio: number) => formatPercent(ratio * 100, 0);

/** Çubuk oranı: gerçekleşen / bütçe; bütçe sıfırsa gerçekleşen varsa 2, yoksa 0 (çubuk görünsün). */
export const ratioOf = (budget: number, actual: number) => budget > 0 ? actual / budget : actual > 0 ? 2 : 0;

/** Ortak ölçek tavanı (bütçeye oran): en az 1,2; en büyük orana göre 0,1 basamakla yukarı yuvarlanır. */
export function scaleMax(rows: { budget: number; actual: number }[], floor = 1.2): number {
  const peak = Math.max(floor, ...rows.map(row => ratioOf(row.budget, row.actual)));
  return Math.ceil(peak * 10 - 1e-9) / 10;
}

/** Ekran okuyucu cümlesi: "Satış: bütçe ₺1.200.000, gerçekleşen ₺1.350.000, +₺150.000 (+%12,5 aşım)". */
export function varianceSentence(name: string, budget: number, actual: number, tolerance = .02): string {
  const { amount } = variance(budget, actual, tolerance);
  return `${name}: bütçe ${moneyFull(budget)}, gerçekleşen ${moneyFull(actual)}, ${signedMoney(amount)} (${variancePercentText(budget, actual, tolerance)})`;
}

.root { container-type: inline-size; display: grid; min-width: 0; gap: var(--space-3); padding: var(--space-6); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); color: var(--foreground); }
.header { display: flex; flex-wrap: wrap; align-items: flex-start; justify-content: space-between; gap: var(--space-3); margin-bottom: var(--space-2); }
.title { margin: 0; font-family: var(--font-display); font-size: var(--text-xl); font-weight: 500; letter-spacing: var(--tracking-display); }
.subtitle { margin: 2px 0 0; color: var(--text-secondary); font-size: var(--text-sm); }
.scaleStrip { display: grid; grid-template-columns: minmax(10rem, 14rem) minmax(0, 1fr) 9rem 9.5rem 1.5rem; gap: var(--space-3); padding: 0 var(--space-3); }
.scaleTrack { position: relative; grid-column: 2; height: 1rem; }
.tick { position: absolute; top: 0; transform: translateX(-50%); color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.tick[data-budget] { color: var(--foreground); font-weight: 500; }
.list, .items { display: grid; gap: var(--space-1); margin: 0; padding: 0; list-style: none; }
.row { display: grid; grid-template-columns: minmax(10rem, 14rem) minmax(0, 1fr) 9rem 9.5rem 1.5rem; align-items: center; gap: var(--space-3); width: 100%; min-height: 3.5rem; padding: var(--space-2) var(--space-3); border: 0; border-radius: var(--radius-control); background: transparent; color: inherit; font: inherit; text-align: left; }
button.row { cursor: pointer; }
button.row:hover { background: var(--surface-muted); }
button.row:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: var(--focus-outline-offset, 2px); }
.total { border-bottom: 1px solid var(--border); border-radius: 0; font-weight: 500; }
.nested { min-height: 2.75rem; font-size: var(--text-sm); }
.nested .name { position: relative; padding-left: var(--space-5); color: var(--text-secondary); }
/* Alt kırılım kategoriden bir basamak geridedir: ince ve soluk çubuk, küçük yazı, kategoriye bağlayan ince çizgi. */
.nested .name::before { content: ""; position: absolute; top: -0.6rem; bottom: -0.6rem; left: calc(var(--space-2) + 1px); width: 1px; background: var(--border); }
.nested .bar { height: .4375rem; }
.nested .fill { opacity: .55; }
.nested .over { opacity: .8; }
.nested .marker { width: 1.5px; }
.nested .amounts b { font-weight: 400; font-size: var(--text-xs); }
.nested .variance { font-size: var(--text-xs); }
.nested .variance small { font-size: 11px; }
.name { display: flex; align-items: center; gap: var(--space-2); min-width: 0; }
.nameText { min-width: 0; overflow-wrap: anywhere; }
.bar { position: relative; display: block; height: .75rem; border-radius: 999px; background: var(--surface-muted); overflow: hidden; }
.fill { position: absolute; inset: 0 auto 0 0; border-radius: 999px 0 0 999px; background: var(--accent); opacity: .85; transition: width var(--duration-considered) var(--ease-standard); }
.fill[data-kind="under"] { background: var(--success); }
.over { position: absolute; top: 0; bottom: 0; background: var(--danger); transition: width var(--duration-considered) var(--ease-standard), left var(--duration-considered) var(--ease-standard); }
.marker { position: absolute; top: 0; bottom: 0; width: 2px; margin-left: -1px; background: var(--foreground); }
.amounts { display: grid; gap: 1px; font-variant-numeric: tabular-nums; text-align: right; }
.amounts b { font-weight: 500; }
.amounts span { color: var(--text-muted); font-size: var(--text-xs); }
.variance { display: grid; gap: 1px; font-variant-numeric: tabular-nums; text-align: right; font-size: var(--text-sm); }
.variance small { font-size: var(--text-xs); }
.variance[data-kind="over"] { color: var(--danger); }
.variance[data-kind="under"] { color: var(--success); }
.variance[data-kind="on"] { color: var(--text-secondary); }
.chevron { color: var(--text-muted); transition: transform var(--duration-standard) var(--ease-spring); }
.chevron[data-open] { transform: rotate(180deg); }
.items { padding-left: 0; }
.legend { display: flex; flex-wrap: wrap; gap: var(--space-1) var(--space-4); margin: var(--space-2) 0 0; padding: 0; list-style: none; color: var(--text-secondary); font-size: var(--text-xs); }
.legend li { display: inline-flex; align-items: center; gap: var(--space-2); }
.keyFill, .keyOver, .keyBand { width: 1rem; height: .5rem; border-radius: 3px; }
.keyFill { background: var(--accent); }
.keyOver { background: var(--danger); }
.keyBand { background: var(--surface-muted); border: 1px solid var(--border-strong); }
.keyMarker { width: 2px; height: .875rem; background: var(--foreground); }
.error { display: flex; align-items: center; justify-content: center; gap: var(--space-3); padding: var(--space-8) 0; color: var(--danger); }
.empty { margin: 0; padding: var(--space-8) 0; color: var(--text-muted); text-align: center; }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
@container (max-width: 760px) {
  .scaleStrip { grid-template-columns: minmax(0, 1fr); }
  .scaleTrack { grid-column: 1; }
  .row { grid-template-columns: minmax(0, 1fr) auto 1.5rem; grid-template-areas: "name amounts chevron" "bar bar bar" "variance variance variance"; min-height: 3.75rem; row-gap: var(--space-1); }
  .row > :nth-child(1) { grid-area: name; }
  .row > :nth-child(2) { grid-area: bar; }
  .row > :nth-child(3) { grid-area: amounts; }
  .row > :nth-child(4) { grid-area: variance; text-align: left; display: flex; gap: var(--space-2); align-items: baseline; }
  .row > :nth-child(5) { grid-area: chevron; }
  .nested .name { padding-left: var(--space-4); }
  .periods { width: 100%; }
}
@container (max-width: 520px) { .root { padding: var(--space-4); } }
.root[data-reduced] .fill, .root[data-reduced] .over, .root[data-reduced] .chevron { transition: none; }
@media (prefers-reduced-motion: reduce) { .fill, .over, .chevron { transition: none; } }

"use client";

import { useEffect, useId, useMemo, useRef, useState, type KeyboardEvent } from "react";
import { AnimatePresence, motion } from "motion/react";
import { AnimatedCounter } from "../animated-counter/animated-counter";
import { Avatar } from "../avatar/avatar";
import { Button } from "../button/button";
import { useReducedMotionSafe } from "../lib/viz-utils";
import SegmentedControl from "../segmented-control/segmented-control";
import { Skeleton } from "../skeleton/skeleton";
import { kindWord, moneyShort, ratioOf, resolveDepartment, scaleMax, scalePercent, signedMoney, variance, variancePercentText, varianceSentence, type VarianceDepartment, type VarianceItem } from "./budget-variance-format";
import styles from "./budget-variance.module.css";

export type { VarianceDepartment, VarianceItem };
export interface VariancePeriod { value: string; label: string }

/** Planlanan ile gerçekleşen harcamayı bölüm bazında hizalı çubuklarla karşılaştırmak için kullanın; burada tüm kalemler gider sayılır (altında kalmak olumlu, aşmak olumsuzdur). Çok sayıda birim için sıralanabilir tablo daha doğrudur. */
export interface BudgetVarianceProps {
  departments: VarianceDepartment[];
  periods: VariancePeriod[];
  period: string;
  onPeriodChange: (value: string) => void;
  title?: string | undefined;
  /** Alt satır: dönem açıklaması, örneğin "Eylül 2026" (ABACUS `date.monthName`). */
  subtitle?: string | undefined;
  /** "Toplam" satırının adı. */
  totalLabel?: string | undefined;
  /** "Plana uygun" bandı: bütçeye oranla (varsayılan 0,02). */
  tolerance?: number | undefined;
  /** Ortak ölçek tavanı (bütçeye oran); verilmezse veriden, en az 1,2. Dönemler arasında sabit kalması için dışarıdan verilebilir. */
  scale?: number | undefined;
  /** Bir bölüm açılınca çağrılır (kalemleri tembel yüklemek için). */
  onOpen?: ((key: string) => void) | undefined;
  status?: "ready" | "loading" | "error" | undefined;
  onRetry?: (() => void) | undefined;
}

interface RowProps { name: string; owner?: string | undefined; budget: number; actual: number; scale: number; tolerance: number; toggle?: { open: boolean; controls: string; onClick: () => void; onKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => void; register: (node: HTMLButtonElement | null) => void } | undefined; strong?: boolean | undefined; nested?: boolean | undefined }

function Row({ name, owner, budget, actual, scale, tolerance, toggle, strong, nested }: RowProps) {
  const ratio = ratioOf(budget, actual);
  const { amount, kind } = variance(budget, actual, tolerance);
  const cut = 1 / scale, fill = Math.min(ratio, 1) / scale, over = Math.max(ratio - 1, 0) / scale;
  const body = <>
    <span className={styles.name}>{owner && <Avatar name={owner} size="sm" aria-hidden="true" />}<span className={styles.nameText}>{name}</span></span>
    <span className={styles.bar} aria-hidden="true">
      <span className={styles.fill} data-kind={kind} style={{ width: `${fill * 100}%` }} />
      {over > 0 && <span className={styles.over} style={{ left: `${cut * 100}%`, width: `${over * 100}%` }} />}
      <span className={styles.marker} style={{ left: `${cut * 100}%` }} />
    </span>
    <span className={styles.amounts} aria-hidden="true"><b><AnimatedCounter value={Math.round(actual)} prefix="₺" /></b><span>/ {moneyShort(budget)}</span></span>
    <span className={styles.variance} data-kind={kind} aria-hidden="true"><span>{signedMoney(amount)}</span><small>{variancePercentText(budget, actual, tolerance)}</small></span>
    {toggle && <span className={styles.chevron} data-open={toggle.open || undefined} aria-hidden="true">▾</span>}
  </>;
  const className = [styles.row, strong ? styles.total : "", nested ? styles.nested : ""].join(" ");
  if (toggle) return <button type="button" ref={toggle.register} className={className} aria-expanded={toggle.open} aria-controls={toggle.controls} aria-label={varianceSentence(name, budget, actual, tolerance)} onClick={toggle.onClick} onKeyDown={toggle.onKeyDown}>{body}</button>;
  return <div className={className} role="group" aria-label={varianceSentence(name, budget, actual, tolerance)}>{body}</div>;
}

export function BudgetVariance({ departments, periods, period, onPeriodChange, title = "Bütçe sapması", subtitle, totalLabel = "Toplam işletme gideri", tolerance = .02, scale, onOpen, status = "ready", onRetry }: BudgetVarianceProps) {
  const reduced = useReducedMotionSafe();
  const baseId = useId();
  const [open, setOpen] = useState<string | null>(null);
  const [announce, setAnnounce] = useState("");
  const buttons = useRef(new Map<string, HTMLButtonElement>());
  const resolved = useMemo(() => departments.map(resolveDepartment), [departments]);
  const totalBudget = resolved.reduce((sum, row) => sum + row.budget, 0), totalActual = resolved.reduce((sum, row) => sum + row.actual, 0);
  const maxRatio = useMemo(() => scale ?? scaleMax([...resolved, ...resolved.flatMap(row => row.items), { budget: totalBudget, actual: totalActual }]), [scale, resolved, totalBudget, totalActual]);
  const ticks = [0, .5, 1].filter(tick => tick <= maxRatio);

  // Dönem değişince yeni dönem ve toplam kibar canlı bölgede duyurulur.
  const firstRun = useRef(true);
  useEffect(() => {
    if (firstRun.current) { firstRun.current = false; return; }
    if (status === "ready" && resolved.length) setAnnounce(`${periods.find(item => item.value === period)?.label ?? ""}: ${varianceSentence(totalLabel, totalBudget, totalActual, tolerance)}`);
  }, [period]); // eslint-disable-line react-hooks/exhaustive-deps

  const keys = resolved.map(row => row.key);
  const onKeyDown = (key: string) => (event: KeyboardEvent<HTMLButtonElement>) => {
    const at = keys.indexOf(key);
    const next = event.key === "ArrowDown" ? at + 1 : event.key === "ArrowUp" ? at - 1 : event.key === "Home" ? 0 : event.key === "End" ? keys.length - 1 : null;
    if (next === null) return;
    event.preventDefault();
    buttons.current.get(keys[Math.min(Math.max(next, 0), keys.length - 1)] ?? "")?.focus();
  };
  const toggle = (key: string) => { const next = open === key ? null : key; setOpen(next); if (next) onOpen?.(next); };

  const periodSwitch = <SegmentedControl label="Dönem" value={period} onValueChange={onPeriodChange} options={periods} />;

  return <section className={styles.root} data-reduced={reduced || undefined} aria-label={title}>
    <header className={styles.header}>
      <div><h3 className={styles.title}>{title}</h3>{subtitle && <p className={styles.subtitle}>{subtitle}</p>}</div>
      <div className={styles.periods}>{periodSwitch}</div>
    </header>

    {status === "loading" && <Skeleton label="Bütçe verisi yükleniyor" lines={6} />}
    {status === "error" && <div className={styles.error} role="alert"><span>Yüklenemedi.</span>{onRetry && <Button size="sm" variant="secondary" onClick={onRetry}>Yeniden dene</Button>}</div>}
    {status === "ready" && !resolved.length && <p className={styles.empty}>Bütçe verisi yok.</p>}

    {status === "ready" && resolved.length > 0 && <>
      <div className={styles.scaleStrip} aria-hidden="true"><span className={styles.scaleTrack}>{ticks.map(tick => <span key={tick} className={styles.tick} data-budget={tick === 1 || undefined} style={{ left: `${(tick / maxRatio) * 100}%` }}>{scalePercent(tick)}</span>)}</span></div>
      <Row name={totalLabel} budget={totalBudget} actual={totalActual} scale={maxRatio} tolerance={tolerance} strong />
      <ul className={styles.list}>
        {resolved.map(row => {
          const isOpen = open === row.key, panelId = `${baseId}-${row.key}`;
          return <li key={row.key}>
            <Row name={row.name} owner={row.owner} budget={row.budget} actual={row.actual} scale={maxRatio} tolerance={tolerance}
              toggle={row.items.length ? { open: isOpen, controls: panelId, onClick: () => toggle(row.key), onKeyDown: onKeyDown(row.key), register: node => { if (node) buttons.current.set(row.key, node); else buttons.current.delete(row.key); } } : undefined} />
            <AnimatePresence initial={false}>
              {isOpen && <motion.ul key="items" id={panelId} className={styles.items} initial={reduced ? false : { height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { height: 0, opacity: 0, transition: { duration: .14 } }} transition={{ duration: reduced ? 0 : .26, ease: [.22, 1, .36, 1] }} style={{ overflow: "hidden" }}>
                {row.items.map(item => <li key={item.key}><Row name={item.name} budget={item.budget} actual={item.actual} scale={maxRatio} tolerance={tolerance} nested /></li>)}
              </motion.ul>}
            </AnimatePresence>
          </li>;
        })}
      </ul>
      <ul className={styles.legend} aria-hidden="true">
        <li><span className={styles.keyFill} />Gerçekleşen</li><li><span className={styles.keyMarker} />Bütçe</li><li><span className={styles.keyOver} />Bütçe aşımı ({kindWord("over")})</li>
        <li><span className={styles.keyBand} />Plana uygun: bütçe bandı ±{scalePercent(tolerance)}</li>
      </ul>
    </>}
    <p className={styles.srOnly} role="status" aria-live="polite" aria-atomic="true">{announce}</p>
  </section>;
}

export default BudgetVariance;
